completion.code:
prepare_layers(s->name);
int flags = {{pid}} | {{mount}} | CLONE_NEWUTS | CLONE_NEWIPC | {{signal}};
s->pid = clone(container_main, stack + sizeof stack, flags, s);
if (s->pid < 0) { perror("clone"); exit(EXIT_FAILURE); }

snprintf(path, sizeof path, "/run/netns/%s", s->name);
int fd = open(path, O_RDONLY);
if (fd < 0 || {{join}}(fd, {{net}}) < 0) {
    perror("setns net"); exit(EXIT_FAILURE);
}
{{release}}(fd);

mkdir(CG_CAR, 0755);
write_file(CG_CAR "/{{enable}}", "+cpu +memory +pids");
snprintf(path, sizeof path, CG_CAR "/%s", s->name);
mkdir(path, 0755);
if (s->cpu_max) {
    snprintf(path, sizeof path, CG_CAR "/%s/{{cpu}}", s->name);
    write_file(path, s->cpu_max);
}
if (s->mem_max) {
    snprintf(path, sizeof path, CG_CAR "/%s/{{memory}}", s->name);
    write_file(path, s->mem_max);
}

snprintf(path, sizeof path, CG_CAR "/%s/{{members}}", s->name);
write_file(path, "{{self}}");
if (unshare({{view}}) < 0) {
    perror("unshare new cgroup"); exit(EXIT_FAILURE);
}

if (mount(NULL, "/", NULL, {{recursive}} | MS_PRIVATE, NULL) < 0) {
    perror("make / private"); exit(EXIT_FAILURE);
}
snprintf(opts, sizeof opts,
    "lowerdir=" IMAGE ",{{upper}}=" CAR "/run/%s/upper,{{work}}=" CAR "/run/%s/work",
    s->name, s->name);
snprintf(path, sizeof path, CAR "/run/%s/merged", s->name);
if (mount("overlay", path, "{{fs}}", 0, opts) < 0) {
    perror("mount overlay"); exit(EXIT_FAILURE);
}

if ({{cwd}}(path) < 0) { perror("chdir"); exit(EXIT_FAILURE); }
mkdir(".oldroot", 0700);
if ({{pivot}}(".", ".oldroot") < 0) {
    perror("pivot_root"); exit(EXIT_FAILURE);
}
if (chdir("/") < 0) { perror("chdir"); exit(EXIT_FAILURE); }
if ({{detach}}("/.oldroot", {{lazy}}) < 0) {
    perror("umount old root"); exit(EXIT_FAILURE);
}
rmdir("/.oldroot");
